"use strict";(self.webpackChunkwoodpecker=self.webpackChunkwoodpecker||[]).push([["7946"],{57300(e){e.exports=JSON.parse('{"name":"Reviewdog PHPCS","slug":"reviewdog-phpcs","url":"https://github.com/njaaazi/woodpecker-reviewdog-phpcs","description":"Run PHP_CodeSniffer with Reviewdog and report to GitHub","docs":"<h1>Overview</h1>\\n<p>Woodpecker CI plugin that runs <a href=\\"https://github.com/PHPCSStandards/PHP_CodeSniffer\\">PHP_CodeSniffer</a> with <a href=\\"https://github.com/reviewdog/reviewdog\\">Reviewdog</a> and reports findings to GitHub.</p>\\n<p>Based on <a href=\\"https://github.com/mikebronner/action-reviewdog-phpcs\\"><code>mikebronner/action-reviewdog-phpcs</code></a>.</p>\\n<h2>Images</h2>\\n<table>\\n<thead>\\n<tr>\\n<th>Tag</th>\\n<th>PHP</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td><code>njaaazi/woodpecker-reviewdog-phpcs:8.3</code></td>\\n<td>8.3</td>\\n</tr>\\n<tr>\\n<td><code>njaaazi/woodpecker-reviewdog-phpcs:8.4</code></td>\\n<td>8.4</td>\\n</tr>\\n<tr>\\n<td><code>njaaazi/woodpecker-reviewdog-phpcs:8.5</code></td>\\n<td>8.5</td>\\n</tr>\\n<tr>\\n<td><code>njaaazi/woodpecker-reviewdog-phpcs:latest</code></td>\\n<td>8.5</td>\\n</tr>\\n</tbody></table>\\n<h2>Settings</h2>\\n<table>\\n<thead>\\n<tr>\\n<th>Settings Name</th>\\n<th>Default</th>\\n<th>Description</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td><code>github_token</code></td>\\n<td><em>none</em></td>\\n<td>GitHub PAT (<code>repo</code> / <code>public_repo</code>) or GitHub App installation token. Required unless <code>reporter</code> is <code>local</code>.</td>\\n</tr>\\n<tr>\\n<td><code>level</code></td>\\n<td><code>warning</code></td>\\n<td>Reviewdog report level: <code>info</code>, <code>warning</code>, <code>error</code>.</td>\\n</tr>\\n<tr>\\n<td><code>reporter</code></td>\\n<td><code>github-pr-review</code></td>\\n<td>Reviewdog reporter: <code>github-pr-review</code>, <code>github-pr-check</code>, <code>github-check</code>.</td>\\n</tr>\\n<tr>\\n<td><code>standard</code></td>\\n<td><code>PSR1,PSR2,PSR12</code></td>\\n<td>PHPCS coding standard or path to a ruleset.</td>\\n</tr>\\n<tr>\\n<td><code>target_directory</code></td>\\n<td><code>src</code></td>\\n<td>Directory to scan.</td>\\n</tr>\\n<tr>\\n<td><code>executable</code></td>\\n<td><code>/usr/local/bin/phpcs.phar</code></td>\\n<td>PHPCS executable. Override for a project-local binary.</td>\\n</tr>\\n<tr>\\n<td><code>fail_on_error</code></td>\\n<td><code>false</code></td>\\n<td>If <code>true</code>, Reviewdog exits 1 when it finds any issue.</td>\\n</tr>\\n<tr>\\n<td><code>changed_only</code></td>\\n<td><code>false</code></td>\\n<td>If <code>true</code>, lint only the PHP files the PR changed under <code>target_directory</code> (from <code>CI_PIPELINE_FILES</code>). Lints everything when that list is empty.</td>\\n</tr>\\n</tbody></table>\\n<p><code>github-pr-review</code> posts inline GitHub PR comments as the token\'s identity. Use this step on <code>pull_request</code> events. <code>github-check</code> and <code>github-pr-check</code> need an App installation token. Store <code>github_token</code> using <a href=\\"https://woodpecker-ci.org/docs/usage/secrets\\">Woodpecker secrets</a>.</p>\\n<h2>Examples</h2>\\n<pre><code class=\\"language-yaml\\">steps:\\n  phpcs:\\n    image: njaaazi/woodpecker-reviewdog-phpcs:8.4\\n    settings:\\n      github_token:\\n        from_secret: github_token\\n      level: warning\\n      reporter: github-pr-review\\n      standard: PSR1,PSR2,PSR12\\n      target_directory: src\\n    when:\\n      event: pull_request\\n</code></pre>\\n","tags":["php","phpcs","reviewdog","lint"],"author":"Njazi Shehu","containerImage":"njaaazi/woodpecker-reviewdog-phpcs","containerImageUrl":"https://hub.docker.com/r/njaaazi/woodpecker-reviewdog-phpcs","verified":false}')}}]);